function damageColoss(coloss,amount){if(coloss.dead)return;coloss.health=Math.max(0,coloss.health-amount);const ratio=coloss.health/coloss.maxHealth;coloss.bar.fill.scale.x=ratio;coloss.bar.fill.position.x=-(1-ratio)*coloss.bar.width/2;dust(coloss.g.position,12,coloss.variant.glow);playSound('bot');if(coloss.health<=0){coloss.dead=true;coloss.bar.g.visible=false;coloss.g.rotation.z=Math.PI/2;coins(coloss.variant.loot);xp(coloss.variant.xp);if(coloss.roundEnemy)recordRoundKill();for(let i=0;i<10;i++){const reward=treat(coloss.g.position.x+(Math.random()-.5)*6,coloss.g.position.z+(Math.random()-.5)*6,17000+coloss.index*100+i);reward.position.y=.9+Math.random()*1.2;reward.userData.baseY=reward.position.y;}const partner=coloss.partner;partner.enraged=true;partner.attackCooldown=.3;showToast(`${coloss.variant.name} caiu! A parceira do colosso entrou em fúria.`);}}
