function updateBoss(dt){const boss=melzinhaBoss;if(!boss)return;boss.aura.rotation.z+=dt*1.7;if(boss.defeated)return;const distance=dist(boss.g.position,player.pos);if(!boss.active){if(state.treats>=90&&distance<10){boss.active=true;boss.phase='telegraph';boss.timer=1.2;$('bossHud').hidden=false;showToast('MELZINHA acordou! Esquive das investidas.');}return;}boss.g.lookAt(player.pos.x,boss.g.position.y,player.pos.z);boss.hitCooldown=Math.max(0,boss.hitCooldown-dt);if(boss.phase==='telegraph'){boss.timer-=dt;boss.aura.scale.setScalar(1+Math.sin(state.time*16)*.22);if(boss.timer<=0){boss.phase='dash';boss.timer=.7;boss.dashDir.set(player.pos.x-boss.g.position.x,0,player.pos.z-boss.g.position.z).normalize();playSound('bark');}}else if(boss.phase==='dash'){boss.g.position.addScaledVector(boss.dashDir,10.5*dt);if(distance<1.65&&boss.hitCooldown<=0){boss.hitCooldown=.9;player.moveVelocity.addScaledVector(boss.dashDir,9);shake=.26;showToast('Investida da Melzinha! Dê dash para escapar.');}boss.timer-=dt;if(boss.timer<=0){boss.phase='recover';boss.timer=.85;}}else{boss.timer-=dt;if(boss.timer<=0){boss.phase='telegraph';boss.timer=.72;}}}
function damageBoss(amount){const boss=melzinhaBoss;if(!boss||boss.defeated)return;boss.health=Math.max(0,boss.health-amount);$('bossFill').style.width=`${boss.health/boss.maxHealth*100}%`;dust(boss.g.position,8,'#ffb95f');playSound('bot');if(boss.health===0){boss.defeated=true;boss.active=false;$('bossHud').hidden=true;coins(1200);xp(300);showToast('Melzinha foi convencida pelo petisco lendário! Vitória no Morro.');}}
function cameraUpdate(dt){const f=new THREE.Vector3(Math.sin(player.cameraYaw),0,Math.cos(player.cameraYaw));if(player.aiming){const eye=player.pos.clone().addScaledVector(f,.38);eye.y=1.08;camPos.lerp(eye,1-Math.exp(-dt*22));camLook.copy(eye).addScaledVector(f,32);camLook.y+=Math.sin(player.cameraPitch)*32;camera.fov=66;barkView.visible=true;barkView.position.lerp(new THREE.Vector3(0,-.43,-.72+player.firing*.16),1-Math.exp(-dt*22));barkView.rotation.x=THREE.MathUtils.lerp(barkView.rotation.x,.04+player.firing*.26,1-Math.exp(-dt*20));barkView.mouth.rotation.x=THREE.MathUtils.lerp(barkView.mouth.rotation.x,.03+player.firing*1.15,1-Math.exp(-dt*25));barkView.scale.setScalar(1+player.firing*.12);}else{const behind=player.pos.clone().addScaledVector(f,-8.2);behind.y=5.3+player.cameraPitch*5;camPos.lerp(behind,1-Math.exp(-dt*6));camLook.lerp(new THREE.Vector3(player.pos.x+f.x*1.1,1.05,player.pos.z+f.z*1.1),1-Math.exp(-dt*8));camera.fov=58;barkView.visible=false;}camera.position.copy(camPos);camera.position.x+=Math.sin(state.time*28)*shake;camera.position.y+=Math.cos(state.time*31)*shake;shake=Math.max(0,shake-dt*.8);camera.lookAt(camLook);camera.updateProjectionMatrix();const shell=document.querySelector('.game-shell');shell.classList.toggle('aiming',player.aiming);shell.classList.toggle('firing',player.firing>.03);}
function canAct(){return state.running&&!state.paused;}
function jump(){if(!canAct()||!player.onGround)return;const power=state.upgrades.jump,target=climbPoints.filter(p=>p.height>player.groundY+.12&&p.height<=player.groundY+2.35+power*.42&&Math.hypot(player.pos.x-p.x,player.pos.z-p.z)<p.radius+1.8+power*.12).sort((a,b)=>a.height-b.height)[0];player.onGround=false;player.climbTarget=target||null;player.velocity.y=(target?10.4:9.2)+power*.8;player.action='jump';player.actionUntil=.42;playSound('dash');}
function dash(){if(!canAct()||player.dashCooldown>0||player.moveVelocity.lengthSq()<.6)return;player.dash=.34+state.upgrades.dash*.018;player.dashCooldown=Math.max(.28,1.05-state.upgrades.dash*.085);player.action='dash';player.actionUntil=.28;dust(player.pos,7,'#fff1be');playSound('dash');}
function bark(){if(!canAct()||ui.barkCooldown.style.display==='block')return;const boost=state.upgrades.bark,range=3.4+boost*.45,damage=1+Math.floor(boost/3)+Math.floor(state.puppies/5);player.action='bark';player.actionUntil=.35;shake=.24;playSound('bark');ui.barkCooldown.style.display='block';ui.barkCooldown.animate([{transform:'scaleY(1)'},{transform:'scaleY(0)'}],{duration:Math.max(480,1400-boost*65),easing:'linear'});setTimeout(()=>ui.barkCooldown.style.display='none',Math.max(480,1400-boost*65));shockwave(player.pos);let hits=0;objects.forEach(o=>{if(!o.userData.broken&&dist(o.position,player.pos)<3.2+state.upgrades.force*.22+boost*.38&&state.power>=o.userData.required){destroy(o);hits++;}});chaosBots.forEach(bot=>{if(!bot.disabled&&dist(bot.g.position,player.pos)<range)disableBot(bot,damage);});colossi.forEach(coloss=>{if(!coloss.dead&&dist(coloss.g.position,player.pos)<range+1.6)damageColoss(coloss,damage*.8);if(coloss.partner.enraged&&!coloss.partner.dead&&dist(coloss.partner.g.position,player.pos)<range)damageColossPartner(coloss.partner,damage);});if(melzinhaBoss?.active&&!melzinhaBoss.defeated&&dist(melzinhaBoss.g.position,player.pos)<range+.4)damageBoss(4+boost*1.5);birdList.forEach(b=>{if(b.flying<=0&&dist(b.g.position,player.pos)<range+.6){b.flying=2.5;state.birds++;}});if(!hits)showToast('AUUU! Nada frágil o suficiente por perto.');}
function barkShot(){if(!canAct()||!player.aiming||!player.aimHeld||player.fireCooldown>0)return;const voice=state.upgrades.ammo,fire=voice>0,critical=Math.random()<state.upgrades.crit*.07,color=critical?'#fff0a2':fire?'#ff7d3f':'#9fefff';player.fireCooldown=Math.max(.075,.19-voice*.009);player.firing=.18;player.action='barkShot';player.actionUntil=.18;shake=.055;playSound('bark');const dir=new THREE.Vector3();camera.getWorldDirection(dir);const origin=camera.position.clone().addScaledVector(dir,.72),shot=new THREE.Group();shot.position.copy(origin);shot.quaternion.setFromUnitVectors(new THREE.Vector3(0,0,1),dir);const core=new THREE.Mesh(new THREE.SphereGeometry(.13+voice*.008,10,8),new THREE.MeshBasicMaterial({color})),trail=new THREE.Mesh(new THREE.CylinderGeometry(.04,.085,.86,7),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.78}));trail.rotation.x=Math.PI/2;trail.position.z=-.43;core.castShadow=trail.castShadow=false;shot.add(core,trail);scene.add(shot);projectiles.push({mesh:shot,dir,speed:39+voice*1.8+state.upgrades.range*1.2,life:2.45+state.upgrades.range*.23,power:1+Math.floor(voice/2)+(critical?2+state.upgrades.crit:0)});dust(origin,12,critical?'#fff3a6':fire?'#ff713c':'#9fefff');}
function sniff(){if(!canAct())return;player.action='sniff';player.actionUntil=.6;playSound('collect');const near=collectibles.filter(c=>!c.userData.claimed).sort((a,b)=>a.position.distanceToSquared(player.pos)-b.position.distanceToSquared(player.pos)).slice(0,5);near.forEach(c=>{const r=mesh(new THREE.TorusGeometry(.7,.045,8,20),material('#ffe168'),c.position.x,.12,c.position.z);r.rotation.x=-Math.PI/2;r.castShadow=false;const start=performance.now();const go=t=>{const p=Math.min(1,(t-start)/1350);r.scale.setScalar(1+p*2);r.material.opacity=1-p;if(p<1)requestAnimationFrame(go);else scene.remove(r);};requestAnimationFrame(go);});showToast(near.length?'O focinho aponta para petiscos brilhantes!':'Seu focinho diz: missão cumprida!');}
function dig(){if(!canAct())return;const near=digSpots.find(d=>!d.userData.dug&&dist(d.position,player.pos)<2);if(!near){showToast('Procure um círculo escuro na areia para escavar.');return;}near.userData.dug=true;near.material.color.set('#6e4c32');player.action='dig';player.actionUntil=.7;playSound('dig');state.treasures++;coins(70+state.upgrades.dig*22);dust(near.position,11,'#b5854c');const bonus=treat(near.position.x+.6,near.position.z,1000+state.treasures);bonus.userData.baseY=.6;showToast('Tesouro desenterrado! + moedas e um petisco.');progress();}
function collect(c){if(c.userData.claimed)return;c.userData.claimed=true;state.treats++;const value=(c.userData.legendary?100:c.userData.rare?35:c.userData.healing?20:10)*(1+state.upgrades.luck*.12)*state.multiplier;coins(Math.round(value));xp(c.userData.legendary?100:c.userData.rare?35:12);if(c.userData.healing){const restored=22+state.upgrades.secret*3;player.health=Math.min(100,player.health+restored);dust(c.position,12,'#62ff9a');showToast(`PETISCO VERDE! +${restored} energia.`);}else dust(c.position,8,c.userData.legendary?'#d1a7ff':'#ffd764');state.missions[0].value++;playSound('collect');scene.remove(c);if(c.userData.rare)showToast(c.userData.legendary?'PETISCO LENDÁRIO! Que faro.':'Petisco dourado! Que brilho.');progress();}
function destroy(o){o.userData.broken=true;state.destroyed++;state.missions[1].value++;coins(Math.round((18+o.userData.required*7)*state.multiplier));xp(11);playSound('crash');dust(o.position,14,'#e48958');scene.remove(o);showToast(`CRASH! ${o.userData.name[0].toUpperCase()+o.userData.name.slice(1)} virou confete.`);progress();}
function dust(pos,n,color){for(let i=0;i<n;i++){const m=mesh(new THREE.BoxGeometry(.13+Math.random()*.14,.13+Math.random()*.14,.13+Math.random()*.14),new THREE.MeshBasicMaterial({color,transparent:true,opacity:1}),pos.x+(Math.random()-.5)*.5,pos.y+.3,pos.z+(Math.random()-.5)*.5);m.castShadow=false;particles.push({mesh:m,vel:new THREE.Vector3((Math.random()-.5)*4,1+Math.random()*4,(Math.random()-.5)*4),life:.45+Math.random()*.4,max:.85});}}
function shockwave(pos){const ring=mesh(new THREE.TorusGeometry(.4,.08,8,32),new THREE.MeshBasicMaterial({color:'#fff2a5',transparent:true,opacity:.9}),pos.x,.12,pos.z);ring.rotation.x=-Math.PI/2;ring.castShadow=false;const start=performance.now(),go=t=>{const p=Math.min(1,(t-start)/450);ring.scale.setScalar(1+p*9);ring.material.opacity=1-p;if(p<1)requestAnimationFrame(go);else scene.remove(ring);};requestAnimationFrame(go);}
function dist(a,b){return Math.hypot(a.x-b.x,a.z-b.z);}function coins(n){state.coins+=n;}function xp(n){state.xp+=n;while(state.xp>=state.level*100){state.xp-=state.level*100;state.level++;state.multiplier=1+Math.floor(state.level/5)*.1;showToast(`NÍVEL ${state.level}! Meyui Beuyi está mais caótico.`);if(state.level%5===0)state.power++;}}
function progress(){state.missions[0].value=state.treats;state.missions[1].value=state.destroyed;state.missions[2].value=state.treasures;state.missions[3].value=state.birds;state.missions.forEach(m=>{if(m.value>=m.goal&&!m.complete){m.complete=true;coins(m.reward);showToast(`Missão concluída: +${m.reward} moedas!`);}});objective();}
function updateRoundUI(){if(!ui.roundNumber)return;ui.roundNumber.textContent=String(roundState.round).padStart(2,'0');if(roundState.active){ui.roundStatus.textContent=roundState.special?`RODADA ESPECIAL · ${roundState.kills} / ${roundState.target}`:`CAPANGAS DO CAOS · ${roundState.kills} / ${roundState.target}`;ui.roundFill.style.width=`${Math.min(100,roundState.kills/roundState.target*100)}%`;}else{ui.roundStatus.textContent=`PRÓXIMA LEVA EM ${Math.max(0,Math.ceil(roundState.cooldown))}s`;ui.roundFill.style.width='0%';}}
function startRound(){roundState.active=true;roundState.kills=0;roundState.special=roundState.round%5===0;const enemyCount=6+roundState.round*3,giantCount=roundState.special?1+Math.floor(roundState.round/10):0;roundState.target=enemyCount+giantCount*2;for(let i=0;i<enemyCount;i++){const angle=i/enemyCount*Math.PI*2+Math.random()*.35,radius=16+Math.random()*12,bot=makeChaosBot(player.pos.x+Math.cos(angle)*radius,player.pos.z+Math.sin(angle)*radius,30000+roundState.round*101+i);bot.roundEnemy=true;bot.maxHealth=3+Math.floor(roundState.round/3);bot.health=bot.maxHealth;bot.damage=9+Math.floor(roundState.round/4)*2;}for(let i=0;i<giantCount;i++){const angle=Math.random()*Math.PI*2,radius=27+i*6,giant=makeColoss(player.pos.x+Math.cos(angle)*radius,player.pos.z+Math.sin(angle)*radius,roundState.round+i,true);giant.roundEnemy=true;giant.partner.roundEnemy=true;giant.aggroRadius=32;giant.leashRadius=80;}showToast(roundState.special?`RODADA ${roundState.round}: CHAMADA DOS COLOSSOS!`:`RODADA ${roundState.round}: a horda chegou!`);updateRoundUI();}
function roundUpdate(dt){if(!roundState.active){roundState.cooldown-=dt;if(roundState.cooldown<=0)startRound();else updateRoundUI();return;}if(roundState.kills>=roundState.target){const reward=90+roundState.round*45;coins(reward);xp(35+roundState.round*12);showToast(`Rodada ${roundState.round} concluída! +${reward} moedas.`);roundState.round++;roundState.active=false;roundState.cooldown=5;roundState.special=false;updateRoundUI();}}
function recordRoundKill(){if(!roundState.active)return;roundState.kills++;updateRoundUI();}
function objective(){if(state.treats<30){state.region='Praia do Petisco';ui.objectiveTitle.textContent='Encontre petiscos pela Praia';ui.objectiveText.textContent='Explore o calçadão e siga o brilho dourado.';ui.objectiveProgress.textContent=`${state.treats} / 30`;ui.objectiveFill.style.width=`${state.treats/30*100}%`;}else if(state.treats<60){state.region='Ruas da Confusão';ui.objectiveTitle.textContent='Desbloqueie as ruas';ui.objectiveText.textContent='Quebre objetos e encontre 60 petiscos.';ui.objectiveProgress.textContent=`${state.treats} / 60`;ui.objectiveFill.style.width=`${state.treats/60*100}%`;}else if(state.treats<90){state.region='Centro do Caos';ui.objectiveTitle.textContent='A cidade está aberta!';ui.objectiveText.textContent='Aventure-se rumo ao Morro do Mistério.';ui.objectiveProgress.textContent=`${state.treats} / 90`;ui.objectiveFill.style.width=`${state.treats/90*100}%`;}else{state.region='Morro do Mistério';ui.objectiveTitle.textContent='O segredo da Ilha do Osso';ui.objectiveText.textContent='Faltam poucos petiscos para o final lendário.';ui.objectiveProgress.textContent=`${state.treats} / 120`;ui.objectiveFill.style.width=`${state.treats/120*100}%`;}}
function renderUpgrades(){const groups=['MOVIMENTO','COMBATE','DEFESA','EXPLORAÇÃO','GANGUE'];ui.upgradeList.innerHTML=groups.map(group=>{const items=upgrades.filter(u=>u.group===group);return `<section class="upgrade-class"><h3>${group}</h3>${items.map(u=>{const level=state.upgrades[u.id],cost=Math.round(u.base*Math.pow(1.52,level));return `<article class="upgrade-item"><span class="upgrade-icon">${u.icon}</span><div><h3>${u.title} <small>NV. ${level}</small></h3><p>${u.desc}</p></div><button data-upgrade="${u.id}" ${state.coins<cost?'disabled':''}>● ${format(cost)}</button></article>`;}).join('')}</section>`;}).join('');ui.upgradeList.querySelectorAll('button').forEach(b=>b.onclick=()=>buy(b.dataset.upgrade));}
function buy(id){const u=upgrades.find(v=>v.id===id),cost=Math.round(u.base*Math.pow(1.52,state.upgrades[id]));if(state.coins<cost)return;state.coins-=cost;state.upgrades[id]++;if(id==='force'&&state.power<state.upgrades.force)state.power=state.upgrades.force;showToast(`${u.title} melhorado! Meyui abana o rabinho.`);updateUI();renderUpgrades();}
function renderMissions(){ui.missionList.innerHTML=state.missions.map(m=>`<article class="mission-item ${m.complete?'complete':''}"><h3>${m.title}</h3><p>${m.text}</p><div class="meter"><i style="width:${Math.min(100,m.value/m.goal*100)}%"></i></div><div class="mission-meta"><span>${Math.min(m.value,m.goal)} / ${m.goal}</span><span>● ${m.reward}</span></div></article>`).join('');}
function openUpgradeModal(){if(!state.running)return;renderUpgrades();state.paused=true;musicElement?.pause();player.aimHeld=false;player.aiming=false;Object.keys(keys).forEach(key=>keys[key]=false);$('upgradeDrawer').hidden=false;showToast('Jogo pausado — escolha um au-mento.');}
function closeUpgradeModal(){if(!$('upgradeDrawer').hidden){$('upgradeDrawer').hidden=true;state.paused=false;musicElement?.play().catch(()=>{});showToast('Meyui voltou à aventura!');}}
function openDrawer(id){if(id==='upgradeDrawer'){openUpgradeModal();return;}document.querySelectorAll('.drawer').forEach(d=>d.hidden=true);if(id==='missionDrawer')renderMissions();$(id).hidden=false;}
function prestige(){if(state.level<20)return;state.cosmic++;state.coins=250;state.level=1;state.xp=0;state.power=1;Object.keys(state.upgrades).forEach(k=>state.upgrades[k]=0);showToast('Prestígio Canino! Biscoito Cósmico ganho.');updateUI();}
function event(){ui.eventText.textContent='CHUVA DE PETISCOS! Vá para o calçadão.';ui.eventBanner.classList.add('show');for(let i=0;i<10;i++){const c=treat(player.pos.x+(Math.random()-.5)*14,player.pos.z+(Math.random()-.5)*14,2000+i);c.position.y=1+Math.random()*3;c.userData.baseY=c.position.y;}setTimeout(()=>ui.eventBanner.classList.remove('show'),5000);}
function updateUI(){progressUI();ui.coins.textContent=format(state.coins);ui.drawerCoins.textContent=format(state.coins);ui.cosmic.textContent=state.cosmic;ui.level.textContent=state.level;ui.xpLabel.textContent=`${Math.floor(state.xp)} / ${state.level*100} XP`;ui.xpFill.style.width=`${state.xp/(state.level*100)*100}%`;ui.treats.textContent=state.treats;ui.health.textContent=Math.ceil(player.health);ui.healthFill.style.width=`${player.health}%`;ui.puppyCount.textContent=state.puppies;ui.power.textContent=state.power;ui.powerName.textContent=state.power>=10?'— postes':state.power>=5?'— bancas':'— caixas';ui.multiplier.textContent=`x${state.multiplier.toFixed(1)}`;ui.regionName.textContent=state.region;const icons={sol:'☀',chuva:'🌧',neve:'❄',lava:'🌋',vento:'🍃',furacao:'🌀',tsunami:'🌊'};ui.weatherIcon.textContent=icons[state.weather]||'☀';const p=$('prestigeButton');p.disabled=state.level<20;p.textContent=state.level>=20?'PRESTIGIAR':'INDISPONÍVEL';}
function progressUI(){state.missions[0].value=state.treats;state.missions[1].value=state.destroyed;state.missions[2].value=state.treasures;state.missions[3].value=state.birds;objective();}
function format(n){if(n>=1e12)return(n/1e12).toFixed(1)+'T';if(n>=1e9)return(n/1e9).toFixed(1)+'B';if(n>=1e6)return(n/1e6).toFixed(1)+'M';if(n>=1e3)return(n/1e3).toFixed(1)+'K';return Math.floor(n).toString();}function showToast(text){ui.toast.textContent=text;ui.toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>ui.toast.classList.remove('show'),2200);}
function fireConfetti(bot){bot.attackPose=.22;const origin=bot.g.position.clone();origin.y+=1.15;const dir=player.pos.clone().sub(origin);dir.y=.08;dir.normalize();const ball=mesh(new THREE.SphereGeometry(.12,8,6),new THREE.MeshBasicMaterial({color:bot.flying?'#c98aff':'#ff5e77'}),origin.x,origin.y,origin.z);ball.castShadow=false;enemyProjectiles.push({mesh:ball,dir,speed:13+state.level*.12+(bot.flying?2:0),life:2.2,damage:bot.damage||9});dust(origin,3,bot.flying?'#d6a3ff':'#ff81b0');}
function fireColossBlast(coloss){const origin=coloss.g.position.clone();origin.y=4.2;const dir=player.pos.clone().sub(origin);dir.y=.03;dir.normalize();const ball=mesh(new THREE.SphereGeometry(.26,10,8),new THREE.MeshBasicMaterial({color:coloss.variant.glow}),origin.x,origin.y,origin.z);ball.castShadow=false;enemyProjectiles.push({mesh:ball,dir,speed:10.5+coloss.index,life:3,damage:16+coloss.index*3});dust(origin,8,coloss.variant.glow);}
function firePartnerBlast(partner){const origin=partner.g.position.clone();origin.y=1.5;const dir=player.pos.clone().sub(origin);dir.y=.05;dir.normalize();const ball=mesh(new THREE.SphereGeometry(.17,9,7),new THREE.MeshBasicMaterial({color:partner.coloss.variant.glow}),origin.x,origin.y,origin.z);ball.castShadow=false;enemyProjectiles.push({mesh:ball,dir,speed:16,life:2.2,damage:13+partner.coloss.index*2});dust(origin,4,partner.coloss.variant.glow);}
function hurtMeyui(amount,from){if(player.damageCooldown>0)return;const damage=Math.max(1,Math.round(amount/(1+state.upgrades.armor*.18)));player.health=Math.max(0,player.health-damage);player.damageCooldown=.48;shake=.18;dust(player.pos,8,'#ff6575');if(from)player.moveVelocity.addScaledVector(from,3.8);if(player.health<=0){player.health=100;player.pos.set(-10,0,6);player.moveVelocity.set(0,0,0);showToast('Meyui tirou uma soneca e voltou ao calçadão.');}else showToast(`Ploft! Confete inimigo: -${damage} energia.`);}
function faceHealthBar(entity,bar){const localParentRotation=entity.g.getWorldQuaternion(new THREE.Quaternion()).invert();bar.g.quaternion.copy(localParentRotation.multiply(camera.quaternion));}
function withinTwoChunks(position){const playerChunkX=Math.floor(player.pos.x/CHUNK_SIZE),playerChunkZ=Math.floor(player.pos.z/CHUNK_SIZE),entityChunkX=Math.floor(position.x/CHUNK_SIZE),entityChunkZ=Math.floor(position.z/CHUNK_SIZE);return Math.abs(entityChunkX-playerChunkX)<=CHUNK_RADIUS&&Math.abs(entityChunkZ-playerChunkZ)<=CHUNK_RADIUS;}
function updateColossi(dt){colossi.forEach(coloss=>{const partner=coloss.partner;coloss.aura.rotation.z+=dt*(1.4+coloss.index*.25);if(!coloss.dead){const toPlayer=player.pos.clone().sub(coloss.g.position),distance=toPlayer.length(),inChaseRange=withinTwoChunks(coloss.g.position);toPlayer.y=0;if(toPlayer.lengthSq())toPlayer.normalize();if(!coloss.aware&&inChaseRange){coloss.aware=true;showToast(`${coloss.variant.name} sentiu o latido e começou a perseguição!`);}if(coloss.aware&&!inChaseRange){coloss.aware=false;showToast(`${coloss.variant.name} saiu do raio de dois chunks e voltou à área.`);}if(coloss.aware){coloss.g.lookAt(player.pos.x,coloss.g.position.y,player.pos.z);if(distance>6.2)coloss.g.position.addScaledVector(toPlayer,dt*(3.45+coloss.index*.32));coloss.attackCooldown-=dt;if(distance<22&&coloss.attackCooldown<=0){fireColossBlast(coloss);coloss.attackCooldown=Math.max(.82,1.9-coloss.index*.14);}}else{const homeDirection=coloss.home.clone().sub(coloss.g.position);homeDirection.y=0;if(homeDirection.lengthSq()>.3){homeDirection.normalize();coloss.g.position.addScaledVector(homeDirection,dt*2);coloss.g.lookAt(coloss.home.x,coloss.g.position.y,coloss.home.z);}}faceHealthBar(coloss,coloss.bar);if(!partner.dead){const behind=coloss.g.position.clone().addScaledVector(toPlayer,-3.25);partner.g.position.lerp(behind,1-Math.exp(-dt*5));partner.g.lookAt(coloss.g.position.x,partner.g.position.y,coloss.g.position.z);faceHealthBar(partner,partner.bar);}return;}if(!partner.enraged||partner.dead)return;partner.attackCooldown-=dt;const toward=player.pos.clone().sub(partner.g.position),distance=toward.length();toward.y=0;if(toward.lengthSq())toward.normalize();if(distance<42){partner.g.lookAt(player.pos.x,partner.g.position.y,player.pos.z);if(distance>3.1)partner.g.position.addScaledVector(toward,dt*(3.7+coloss.index*.2));if(distance<15&&partner.attackCooldown<=0){firePartnerBlast(partner);partner.attackCooldown=1.05;}}faceHealthBar(partner,partner.bar);});}
function animateChaosBot(bot){const moving=!bot.disabled&&bot.velocity.lengthSq()>.15,gait=state.time*(moving?12:3)+bot.gait,step=moving?Math.sin(gait):Math.sin(gait)*.12,swing=moving?.82:.08,attack=bot.attackPose||0;bot.limbs.arms.forEach((limb,index)=>limb.rotation.x=attack?(index?-.28:-.98):(index?1:-1)*step*swing);bot.limbs.legs.forEach((limb,index)=>limb.rotation.x=(index?1:-1)*step*swing);bot.rigLimbs.forEach((limb,index)=>limb.rotation.x=index<2?(attack?(index?-.24:-1.05):(index%2?1:-1)*step*.95):(index%2?1:-1)*step*.72);if(bot.model){bot.model.position.y=(moving?Math.abs(step)*.07:Math.sin(gait)*.018);bot.model.rotation.z=attack?.065:(moving?step*.045:0);bot.model.rotation.x=attack?-.065:(moving?Math.abs(step)*.025:0);}if(bot.flying)bot.motionRig.rotation.z=Math.sin(gait)*.12;}
function updateActionHint(){const partner=friendlyDogs.filter(d=>!d.paired).sort((a,b)=>dist(a.g.position,player.pos)-dist(b.g.position,player.pos))[0],digging=digSpots.find(d=>!d.userData.dug&&dist(d.position,player.pos)<2),breakableNear=objects.find(o=>!o.userData.broken&&dist(o.position,player.pos)<3),giant=colossi.find(coloss=>!coloss.dead&&dist(coloss.g.position,player.pos)<38),enemy=chaosBots.find(bot=>!bot.disabled&&dist(bot.g.position,player.pos)<30);let text='';if(partner&&dist(partner.g.position,player.pos)<3)text='[ G ] FORMAR A GANGUE COM ESTE CACHORRO';else if(digging)text='[ F ] ESCAVAR TESOURO';else if(breakableNear)text='[ E ] LATIDO SÍSMICO PARA DESTRUIR';else if(giant)text=`[ SEGURE BOTÃO DIREITO + CLIQUE ] LATIR EM ${giant.variant.name.toUpperCase()}`;else if(enemy)text='[ SEGURE BOTÃO DIREITO + CLIQUE ] MIRAR E LATIR';ui.actionHint.textContent=text;ui.actionHint.classList.toggle('show',Boolean(text));}
function combatUpdate(dt){
  updateColossi(dt);
  chaosBots.forEach(bot=>{if(bot.disabled)return;bot.shotCooldown-=dt;bot.attackPose=Math.max(0,bot.attackPose-dt);const toPlayer=player.pos.clone().sub(bot.g.position),distance=toPlayer.length(),chasing=withinTwoChunks(bot.g.position);toPlayer.y=0;if(toPlayer.lengthSq())toPlayer.normalize();const desired=new THREE.Vector3();if(chasing){if(distance>8.5)desired.copy(toPlayer);else if(distance<4.1)desired.copy(toPlayer).multiplyScalar(-1);else desired.set(-toPlayer.z,0,toPlayer.x).multiplyScalar(bot.seed%2?1:-1);const speed=(bot.flying?4.25:3.05)+(distance>10?.7:0);bot.velocity.lerp(desired.multiplyScalar(speed),1-Math.exp(-dt*6));bot.g.position.addScaledVector(bot.velocity,dt);bot.g.lookAt(player.pos.x,bot.g.position.y,player.pos.z);if(distance<18&&distance>2.3&&bot.shotCooldown<=0){fireConfetti(bot);bot.shotCooldown=Math.max(.5,1.42-state.level*.025-(bot.flying?.15:0));}}else{const patrolAngle=state.time*.72+bot.gait;desired.set(Math.sin(patrolAngle),0,Math.cos(patrolAngle));bot.velocity.lerp(desired.multiplyScalar(bot.flying?1.55:1.1),1-Math.exp(-dt*4));bot.g.position.addScaledVector(bot.velocity,dt);bot.g.lookAt(bot.g.position.x+bot.velocity.x,bot.g.position.y,bot.g.position.z+bot.velocity.z);}if(bot.flying)bot.g.position.y=1.15+Math.sin(state.time*3+bot.seed)*.28;else bot.g.position.y=0;animateChaosBot(bot);const parentRotation=bot.g.getWorldQuaternion(new THREE.Quaternion()).invert();bot.healthBar.quaternion.copy(parentRotation.multiply(camera.quaternion));});
  for(let i=enemyProjectiles.length-1;i>=0;i--){const shot=enemyProjectiles[i];shot.life-=dt;shot.mesh.position.addScaledVector(shot.dir,shot.speed*dt);if(dist(shot.mesh.position,player.pos)<.72){hurtMeyui(shot.damage||9,shot.dir);shot.life=0;}if(shot.life<=0){scene.remove(shot.mesh);enemyProjectiles.splice(i,1);}}
  friendlyDogs.forEach(friend=>{if(friend.paired)return;friend.g.position.y=Math.sin(state.time*3+friend.seed)*.035;friend.g.rotation.y=Math.sin(state.time*.9+friend.seed)*.2;});
  puppyGang.forEach(pup=>{const angle=state.time*.75+pup.index*2.4,target=new THREE.Vector3(player.pos.x+Math.cos(angle)*(1.25+pup.index%3*.3),.06,player.pos.z+Math.sin(angle)*(1.25+pup.index%3*.3));pup.g.position.lerp(target,1-Math.exp(-dt*5));pup.g.rotation.y=angle+Math.PI/2;pup.g.position.y=.08+Math.abs(Math.sin(state.time*7+pup.index))*.05;if(pup.aura){pup.aura.rotation.z+=dt*5;pup.aura.scale.setScalar(1+Math.sin(state.time*6+pup.index)*.16);}pup.attackCooldown-=dt;const targetBot=chaosBots.filter(bot=>!bot.disabled&&dist(bot.g.position,pup.g.position)<7.6).sort((a,b)=>dist(a.g.position,pup.g.position)-dist(b.g.position,pup.g.position))[0],targetColoss=colossi.filter(coloss=>!coloss.dead&&dist(coloss.g.position,pup.g.position)<9.5).sort((a,b)=>dist(a.g.position,pup.g.position)-dist(b.g.position,pup.g.position))[0],targetEnemy=!targetColoss||targetBot&&dist(targetBot.g.position,pup.g.position)<dist(targetColoss.g.position,pup.g.position)?targetBot:targetColoss;if(targetEnemy&&pup.attackCooldown<=0)firePuppyBolt(pup,targetEnemy);});
  for(let i=puppyShots.length-1;i>=0;i--){const shot=puppyShots[i];shot.life-=dt;shot.mesh.position.addScaledVector(shot.dir,shot.speed*dt);const target=chaosBots.find(bot=>!bot.disabled&&shotHitsBot(shot.previous,shot.mesh.position,bot));const bigTarget=!target&&colossi.find(coloss=>!coloss.dead&&shotHitsColoss(shot.previous,shot.mesh.position,coloss));if(target){disableBot(target,shot.damage);dust(target.g.position,7,shot.color);confirmHit(shot.color,false);shot.life=0;}if(bigTarget){damageColoss(bigTarget,shot.damage);dust(bigTarget.g.position,7,shot.color);shot.life=0;}shot.previous.copy(shot.mesh.position);if(shot.life<=0){scene.remove(shot.mesh);puppyShots.splice(i,1);}}
  updateActionHint();
}
function firePuppyBolt(pup,bot){const element=pup.elemental||{color:'#ffe07a',damage:.75,rate:1.05},power=1+state.upgrades.pupPower*.22,origin=pup.g.position.clone();origin.y+=.42;const aim=bot.g.position.clone();aim.y+=bot.flying?1.35:bot.variant?3.2:.9;const dir=aim.sub(origin).normalize(),orb=new THREE.Mesh(new THREE.SphereGeometry(pup.elemental?.12:.075,8,7),new THREE.MeshBasicMaterial({color:element.color}));orb.position.copy(origin);orb.castShadow=false;scene.add(orb);puppyShots.push({mesh:orb,previous:origin.clone(),dir,speed:pup.elemental?21:16,life:.72,damage:element.damage*power,color:element.color});pup.attackCooldown=Math.max(.2,element.rate-state.upgrades.pupPower*.045);dust(origin,pup.elemental?5:2,element.color);}
function drawMiniMap(){const canvas=ui.miniMap;if(!canvas)return;const ctx=canvas.getContext('2d'),size=canvas.width,center=size/2,range=102,scale=center/range,point=(x,z)=>({x:center+(x-player.pos.x)*scale,z:center+(z-player.pos.z)*scale}),rect=(x,z,w,h,color,alpha=1)=>{const p=point(x,z);ctx.globalAlpha=alpha;ctx.fillStyle=color;ctx.fillRect(p.x-w*scale/2,p.z-h*scale/2,w*scale,h*scale);};ctx.clearRect(0,0,size,size);ctx.fillStyle='#091f31';ctx.fillRect(0,0,size,size);ctx.save();ctx.beginPath();ctx.arc(center,center,center-4,0,Math.PI*2);ctx.clip();for(let r=22;r<center;r+=25){ctx.strokeStyle='#bdebf015';ctx.lineWidth=1;ctx.beginPath();ctx.arc(center,center,r,0,Math.PI*2);ctx.stroke();}ctx.strokeStyle='#bdebf02a';ctx.beginPath();ctx.moveTo(0,center);ctx.lineTo(size,center);ctx.moveTo(center,0);ctx.lineTo(center,size);ctx.stroke();
  const biomeColors={areia:'#a88d5e',grama:'#536d58',cidade:'#626e75',morro:'#4d6656'};for(const chunk of terrainChunks.values()){const x=chunk.cx*CHUNK_SIZE+CHUNK_SIZE/2,z=chunk.cz*CHUNK_SIZE+CHUNK_SIZE/2;rect(x,z,CHUNK_SIZE,CHUNK_SIZE,biomeColors[terrainBiome(chunk.cx,chunk.cz)]||'#59666d',.96);if(noise2(chunk.cx,chunk.cz,8)>.44){const vertical=noise2(chunk.cx,chunk.cz,9)>.5;rect(x,z,vertical?6:CHUNK_SIZE,vertical?CHUNK_SIZE:6,'#303b40',.93);}}
  rect(-67,0,150,150,'#2d7189',.95);rect(17,3,175,145,'#887e63',.97);rect(-3,2,38,140,'#9ba19a',.96);rect(38,0,23,120,'#3e484e',.98);solidColliders.forEach(c=>rect(c.x,c.z,c.width,c.depth,'#1d2c36',.72));ctx.globalAlpha=1;
  const dot=(entity,color,r=3)=>{const p=point(entity.position.x,entity.position.z);if(p.x<-5||p.x>size+5||p.z<-5||p.z>size+5)return;ctx.fillStyle=color;ctx.shadowColor=color;ctx.shadowBlur=r>3?8:3;ctx.beginPath();ctx.arc(p.x,p.z,r,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;};chaosBots.forEach(bot=>{if(!bot.disabled)dot(bot.g,bot.flying?'#c896ff':'#ff5d6c',2.8);});colossi.forEach(coloss=>{if(!coloss.dead)dot(coloss.g,coloss.variant.glow,6);if(coloss.partner.enraged&&!coloss.partner.dead)dot(coloss.partner.g,'#ff98ad',3.5);});friendlyDogs.forEach(friend=>{if(!friend.paired)dot(friend.g,'#7ae6c4',2.6);});collectibles.forEach(c=>{if(!c.userData.claimed&&dist(c.position,player.pos)<range)dot(c,c.userData.healing?'#62ff9a':c.userData.legendary?'#c99cff':'#ffdf63',c.userData.healing?2.5:1.55);});puppyGang.forEach(pup=>dot(pup.g,pup.elemental?.color||'#ffab64',1.8));
  ctx.save();ctx.translate(center,center);ctx.rotate(-player.dir);ctx.fillStyle='#fff0a4';ctx.shadowColor='#ffcc55';ctx.shadowBlur=10;ctx.beginPath();ctx.moveTo(0,-9);ctx.lineTo(6,7);ctx.lineTo(-6,7);ctx.closePath();ctx.fill();ctx.restore();ctx.fillStyle='#d6f3f4';ctx.font='900 8px Nunito';ctx.fillText('N',center-3,13);ctx.restore();ctx.strokeStyle='#e6fbfa99';ctx.lineWidth=2;ctx.beginPath();ctx.arc(center,center,center-4,0,Math.PI*2);ctx.stroke();}
